"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[391],{9391:function(e,a,t){t.d(a,{lz:function(){return s},xW:function(){return n}});let n=[{slug:"advisory",name:"1LINE Advisory",shortName:"Advisory",tagline:"Fractional CFO leadership, on a clear monthly cadence",accent:"#0B7A43",accentTailwind:"text-div-advisory",hero:"Financial leadership for owners who have outgrown the bank balance.",summary:"Advisory is 1LINE's fractional CFO practice: financial strategy, forecasting, management reporting, and decision support for owners who need executive-grade finance without hiring a full-time CFO.",audience:["Construction company owners and specialty contractors whose reporting no longer keeps up with the business","Middle-market executives who need a forecast they can defend — to a bank, a surety, or their own team","Owners making consequential calls on hiring, equipment, backlog, and pricing with incomplete numbers"],problems:["Profitable on paper, short on cash — and no one can explain the gap","Month-end reports arrive too late to change anything","Job margins are known only after the job is finished","Growth decisions are made on instinct because the forecast is a guess"],services:[{title:"Financial planning & forecasting",body:"Rolling forecasts tied to backlog, capacity, and cash — updated on a cadence, not rebuilt from scratch each quarter."},{title:"Cash flow management",body:"A maintained 13-week cash view that surfaces shortfalls while there is still time to act on them."},{title:"KPI & management reporting",body:"A short, consistent reporting pack — WIP, margin by job, backlog quality, receivables — written for decisions, not for filing."},{title:"Profitability analysis",body:"Margin bridges that show where profit is made and lost: estimating, labor, change orders, overhead absorption."},{title:"Strategic advisory",body:"A standing financial partner for pricing, hiring, capital purchases, and growth decisions — with the numbers worked before the meeting."}],outcomes:["A forecast the owner, the bank, and the surety can all read the same way","Cash surprises replaced by a 13-week line of sight","Margin problems identified while the job can still be corrected","Decisions documented with their financial reasoning, not reconstructed later"],process:[{step:"Assess",body:"A focused review of your current reporting, WIP, and cash position. You keep the written findings either way."},{step:"Align",body:"We agree the reporting cadence, the KPI set, and the decisions the numbers need to support."},{step:"Operate",body:"Monthly financial leadership on a predictable rhythm — close review, forecast update, and an owner decision session."},{step:"Improve",body:"Each quarter we retire what isn't used and deepen what drives decisions."}],faqs:[{q:"Is Advisory a bookkeeping or tax service?",a:"No. Advisory is forward-looking financial leadership — forecasting, reporting, and decision support. Bookkeeping and tax preparation stay with your existing providers; we work with them and make their output decision-ready."},{q:"Do you only work with construction companies?",a:"Construction finance is our deepest specialty — WIP, retainage, and bonding shape everything we do. The same discipline applies to other owner-led, project- or operations-driven businesses, and we will tell you plainly if your business is not a fit."},{q:"What does an engagement look like month to month?",a:"A defined monthly cadence: reporting pack, updated forecast and 13-week cash view, and a decision session with the owner. Scope is agreed before any engagement begins — no open-ended billing surprises."}]},{slug:"build",name:"1LINE Build",shortName:"Build",tagline:"Launch, operate, and scale a contractor business — on sound economics",accent:"#E86A17",accentTailwind:"text-div-build",hero:"The business side of contracting, built in the right order.",summary:"Build helps skilled tradespeople becoming owners — and established contractors fixing their foundations — put the financial and operating systems in place before growth exposes the gaps.",audience:["Licensed tradespeople starting their first construction company","New contractors whose jobs are fine but whose books, bids, and cash are not","Established firms preparing to scale crews, backlog, or bonding capacity"],problems:["Winning work that loses money because the bid never carried the real overhead","No job-cost system, so every lesson is learned at full price","Licensing, insurance, and filings handled reactively, one notice at a time","Growth funded accidentally — by retainage timing and credit cards"],services:[{title:"Startup planning",body:"Entity, licensing, and compliance sequencing for California contractors, with the financial setup done in the right order — and referrals to licensed professionals where the work requires them."},{title:"Financial controls",body:"A chart of accounts built for job costing, a weekly cash habit, and simple controls that survive a busy season."},{title:"Estimating & business economics",body:"Bid math that carries labor burden, overhead, and target margin — so the price is a decision, not a hope."},{title:"Operating processes",body:"Practical systems for billing, collections, change orders, and close-out that a small team can actually run."},{title:"Scaling readiness",body:"An honest assessment of what breaks next — people, cash, bonding, or systems — before you commit to bigger work."}],outcomes:["Bids priced from real costs, with margin protected on purpose","A job-cost view that shows profit while there is time to act","Filings, insurance, and bonding preparation handled on a calendar, not in a crisis","A 90-day roadmap sequenced by what the business needs first"],process:[{step:"Assess",body:"Where the business stands: licensing, books, bid math, cash, and backlog — scored plainly."},{step:"Sequence",body:"A stage-gated 90-day plan. Foundations before growth, in writing."},{step:"Implement",body:"We build the systems with you — accounts, templates, cadences — using your real jobs as the test data."},{step:"Hand over",body:"You run it. Advisory support remains available when the questions get bigger."}],faqs:[{q:"Does 1LINE perform construction work?",a:"No. Build is business-building support — finance, systems, and operations for contractor businesses. 1LINE does not perform, bid, or supervise licensed construction work."},{q:"I haven't started yet. Is it too early?",a:"It is the cheapest moment to get the economics right. The startup sequence exists precisely so the first year builds on sound bid math and clean books."},{q:"Do you replace my CPA or attorney?",a:"No. Where a step requires a licensed professional — tax filings, legal documents, license counsel — we help you prepare and coordinate, and the licensed professional does that work."}],note:"Build provides business and financial education and advisory support. It is not legal, tax, or licensing advice for any specific situation."},{slug:"intelligence",name:"1LINE Intelligence",shortName:"Intelligence",tagline:"Dashboards, reporting, and automation that turn data into decisions",accent:"#2563EB",accentTailwind:"text-div-intelligence",hero:"Your numbers already know. Intelligence makes them say it plainly.",summary:"Intelligence turns scattered operational and financial data — job cost, WIP, receivables, backlog — into a small set of maintained dashboards and exception reports that owners actually read.",audience:["Companies with real systems (accounting, project management, spreadsheets) but no single operating view","Owners who get five versions of the truth from five reports","Teams spending hours each month assembling the same reporting pack by hand"],problems:["Reports assembled manually, arriving late and differing by who built them","Exceptions — a job slipping, a receivable aging — discovered weeks after the fact","Data entered twice into systems that were supposed to talk to each other","AI tools adopted ad hoc, with no human review of what they produce"],services:[{title:"Management dashboards",body:"One executive view — cash, WIP, margin, backlog, receivables — defined once, refreshed on a cadence, identical for every reader."},{title:"Automated reporting workflows",body:"The monthly pack assembled by process instead of by heroics: imports checked, variances flagged, definitions documented."},{title:"Forecasting models",body:"Driver-based models for cash, backlog burn, and capacity that update from actuals instead of being rebuilt."},{title:"Business intelligence foundations",body:"A KPI dictionary and data-quality checks, so every number on the dashboard has one agreed meaning and a traceable source."},{title:"Practical AI assistance",body:"AI used where it is genuinely useful — exception triage, variance drafting, research assistance — always with human approval before anything is sent, filed, or booked."}],outcomes:["One version of the numbers, available before the meeting instead of after it","Exceptions surfaced weekly, while they are still small","Month-end reporting time cut by process, not by working later","Every figure traceable to its source — a banker or surety can follow the line"],process:[{step:"Map",body:"We inventory your systems, reports, and definitions, and find where the versions diverge."},{step:"Define",body:"A written KPI dictionary: each metric, its formula, its source, its owner."},{step:"Build",body:"Dashboards and workflows built on your existing systems wherever possible — no rip-and-replace by default."},{step:"Run",body:"Refresh cadence, exception review, and quarterly pruning of anything nobody uses."}],faqs:[{q:"Do we need to change our accounting or project systems?",a:"Usually not. Intelligence is designed to sit on top of the systems you already run. If a system genuinely cannot produce what you need, we will show you the evidence before recommending any change."},{q:"Is our data used to train AI models?",a:"No. Client data stays client data. AI assistance, where used, operates under human review and your confidentiality requirements."},{q:"What do you need from us to start?",a:"Access to the reports you already produce and an hour to walk through how decisions get made. The mapping exercise starts from what exists, not from a blank slate."}]},{slug:"academy",name:"1LINE Academy",shortName:"Academy",tagline:"Practical business and finance education — free first, useful always",accent:"#7C3AED",accentTailwind:"text-div-academy",hero:"Learn the numbers the way owners actually use them.",summary:"Academy is 1LINE's education division: free articles, guides, templates, and practical explainers on construction finance and business leadership — built to be useful before anything is ever sold.",audience:["Contractors and business owners who want to read their own financials with confidence","Project managers and operations staff moving toward leadership roles","Finance professionals who want construction-specific depth"],problems:["Generic business advice that ignores how construction cash actually moves","Financial concepts taught as theory, with no worked example from a real job","Templates that look polished and calculate nothing","Courses sold before any free value has been proven"],services:[{title:"Free guides & articles",body:"The Insights library: plain-language, worked-example explanations of WIP, cash flow, margins, bonding, and owner decision-making."},{title:"Templates & tools",body:"Downloadable worksheets — starting with the 13-week cash flow and WIP review checklists in Resources — built to be used the same day."},{title:"Educational series",body:"Sequenced series that build a topic properly: read your financial statements, run your company on numbers, prepare for a lender meeting."},{title:"Courses & community (in development)",body:"Structured courses and a practitioner community are planned as the free library proves what owners actually need. We will announce them here when they are real — not before."}],outcomes:["Owners who can open a WIP schedule and know what to ask","Teams that share one vocabulary for margin, cash, and backlog","Better questions brought to bankers, sureties, CPAs — and to us"],process:[{step:"Read",body:"Start with Insights and the free Resources. No account, no paywall on the fundamentals."},{step:"Apply",body:"Use the worksheets on your own numbers. Every guide ends with the action it supports."},{step:"Go deeper",body:"When a topic needs your actual financials rather than an example, that is where Advisory and Build begin."}],faqs:[{q:"Is Academy content really free?",a:"The articles, guides, and starter templates are free, and that is deliberate: trust is built by being useful first. Paid courses may come later; the free library stays free."},{q:"Is this a substitute for professional advice?",a:"No. Academy is education. It explains how things work and what to ask; decisions for your specific business belong with you and your licensed advisors."},{q:"Who writes Academy content?",a:"Content is produced under the direction of founder Jake Schreiber, a practicing CFO, and reviewed for accuracy before publication. Educational presenters, where used in video, are disclosed as such."}]},{slug:"capital",name:"1LINE Capital",shortName:"Capital",tagline:"Financing readiness, bonding readiness, and enterprise value",accent:"#A97B0F",accentTailwind:"text-div-capital",hero:"Be ready for the lender, the surety, and the buyer — before you need them.",summary:"Capital prepares owners for the moments when outsiders judge the business: a credit line, a bonding increase, a growth investment, or an eventual exit. Preparation and strategy — presented honestly as advisory, not as lending or banking.",audience:["Owners planning growth that will require bank or surety support","Contractors whose bonding capacity is smaller than their ambitions","Owners thinking about value, succession, or exit on a multi-year horizon"],problems:["Financial statements that raise questions a lender has to chase","Working capital consumed by growth itself — more work, less cash","Bonding capacity treated as a verdict instead of a manageable outcome","Exit value left to chance because preparation started at the offer"],services:[{title:"Working capital management",body:"Billing, retainage, and collection disciplines that free the cash growth consumes — often the cheapest financing available."},{title:"Financing readiness",body:"Statements, forecasts, and covenant models assembled the way a lender reads them, with weaknesses addressed before they are discovered."},{title:"Banking & surety relationships",body:"Preparation for bank and surety meetings: the package, the narrative the numbers support, and honest answers to the hard questions."},{title:"Enterprise value & exit preparation",body:"The multi-year work of making a business transferable: clean WIP history, normalized earnings, documented systems, and an owner the business can survive without."}],outcomes:["A lender package that answers questions before they are asked","Bonding conversations held from evidence, not hope","Growth funded deliberately, at a cost you chose","An exit treated as a project with a timeline — not an event that happens to you"],process:[{step:"Score",body:"A capital readiness review across statements, working capital, banking, and bonding — with the gaps ranked."},{step:"Prepare",body:"We close the ranked gaps: reporting quality, cash discipline, covenant visibility."},{step:"Present",body:"You meet your bank or surety with a prepared package and a rehearsed, honest narrative."},{step:"Maintain",body:"Readiness kept current quarterly, so an opportunity never waits on your financials."}],faqs:[{q:"Is 1LINE a lender or investment bank?",a:"No. Capital is preparation and strategic advisory. We do not lend, place securities, or act as a broker. We prepare you to work well with the institutions that do."},{q:"Can you guarantee financing or bonding?",a:"No one honestly can. What we can do is make sure the decision is made on your best, clearest financial presentation — and that fixable weaknesses are fixed first."},{q:"When should exit preparation start?",a:"Years before the exit, ideally. The items buyers discount for — messy WIP, owner dependence, unexplained earnings adjustments — take time to cure. Starting early is most of the value."}],note:"1LINE Capital provides financial preparation and strategic advisory services. It is not a lender, bank, surety, broker-dealer, or investment bank, and it does not guarantee any financing, bonding, or transaction outcome."}],s={name:"1LINE",legalName:"1Line LLC",domain:"1line.llc",url:"https://1line.llc",headline:"Clarity for the decisions that move business forward.",description:"1LINE is a financial leadership and business advisory firm founded by a practicing construction CFO. One clear line from financial information to better business decisions — across Advisory, Build, Intelligence, Academy, and Capital.",email:"hello@1line.llc",linkedin:"https://www.linkedin.com/company/1linecfo/",founded:2024,location:"Southern California"}}}]);